import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:n+1]))
    x = int(data[n+1])
    y = int(data[n+2])

    # Step 1: Element Replacement
    for i in range(n):
        if arr[i] % x == 0:
            arr[i] = y

    # Step 2: Incremental Sum Update (from left to right)
    for i in range(n - 1):
        arr[i] = arr[i] + arr[i + 1]

    # Step 3: Find maximum value
    print(max(arr))

if __name__ == "__main__":
    main()
